BEGIN
IF :System.Form_Status = 'CHANGED' THEN
COMMIT_FORM;
IF :System.Form_Status = 'CHANGED' THEN RAISE FORM_TRIGGER_FAILURE; END IF;
END IF;
pkg_orders.set_status(:ORDERS.ORDER_ID, 'Paid', NULL, NVL(:CTRL.PAY_METHOD, 'Cash'));
Forms_Ddl('COMMIT');
Refresh_Order_Header;
MESSAGE('Order ' || TO_CHAR(:ORDERS.ORDER_ID) || ' is now Paid.');
